import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse(`{"title":"Trae learning map","description":"TraeCode is ByteDance's AI coding IDE (IDE mode + SOLO mode). TraeWork, Doubao, Coze, and Ark are different products. This directory only covers installing TraeCode from the official download page and opening a first project.","frontmatter":{"title":"Trae learning map","description":"TraeCode is ByteDance's AI coding IDE (IDE mode + SOLO mode). TraeWork, Doubao, Coze, and Ark are different products. This directory only covers installing TraeCode from the official download page and opening a first project.","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"products/trae/index.md","filePath":"products/trae/index.md","lastUpdated":1787107158000}`),s={name:"products/trae/index.md"};function o(i,e,d,l,p,c){return r(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="trae-learning-map" tabindex="-1">Trae learning map <a class="header-anchor" href="#trae-learning-map" aria-label="Permalink to &quot;Trae learning map&quot;">​</a></h1><blockquote><p><strong>TraeCode</strong> is the AI coding IDE under the TRAE brand. Official copy (<a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a>): a development tool deeply integrated with AI, covering coding, project understanding, debugging, and change management. You can stay in control as in a traditional IDE, or hand complex work to agents.</p><p>The marketing homepage (<a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a>) lists it next to <strong>TraeWork</strong>: <strong>TraeCode: Your 10x AI Coding Engineer</strong>; <strong>TraeWork: Your Professional AI Work Assistant</strong>. This directory expands TraeCode only.</p></blockquote><h2 id="audience-prerequisites" tabindex="-1">Audience / prerequisites <a class="header-anchor" href="#audience-prerequisites" aria-label="Permalink to &quot;Audience / prerequisites&quot;">​</a></h2><ul><li><strong>Who</strong>: frontend engineers who already use a desktop IDE and want ByteDance&#39;s Cursor analogue.</li><li><strong>Need</strong>: an OS from the official <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a> / <a href="https://docs.trae.cn/ide_get-started-with-trae.md" target="_blank" rel="noreferrer">CN getting started</a> table; a TRAE account.</li><li><strong>Non-goals</strong>: no TraeWork office tutorial; no Doubao / Coze / Ark; no model internals (see Learn LLM); no invented TraeCode CLI commands (the enterprise page says <strong>coming soon</strong>).</li></ul><h2 id="product-family" tabindex="-1">Product family <a class="header-anchor" href="#product-family" aria-label="Permalink to &quot;Product family&quot;">​</a></h2><p>Official first-level entries first. This directory <strong>only expands TraeCode</strong>. Everything else is one row. Names below are copied from official pages opened 2026-08-19.</p><table tabindex="0"><thead><tr><th>Official name</th><th>Official URL</th><th>This site</th></tr></thead><tbody><tr><td><strong>TraeCode</strong> (AI coding IDE)</td><td><a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a> · <a href="https://www.trae.ai/download" target="_blank" rel="noreferrer">Download Center</a></td><td>This directory</td></tr><tr><td><strong>TraeCode docs</strong></td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai · What is TraeCode?</a> · <a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a></td><td>This page · <a href="./trae.html">Tutorial</a></td></tr><tr><td><strong>TraeWork</strong></td><td><a href="https://www.trae.ai/work" target="_blank" rel="noreferrer">www.trae.ai/work</a> · <a href="https://docs.trae.ai/solo/what-is-trae-solo" target="_blank" rel="noreferrer">What is TRAE Work?</a></td><td>One row: office workspace, no tutorial here</td></tr><tr><td><strong>TraeCode Plugin</strong></td><td><a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">Enterprise</a> (copy: VS Code, JetBrains and other mainstream editors)</td><td>One row: embed into an existing editor</td></tr><tr><td><strong>TRAE Enterprise</strong></td><td><a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">www.trae.ai/enterprise</a></td><td>One row: team sales</td></tr><tr><td><strong>TraeCode CLI</strong></td><td>Enterprise page: <strong>coming soon</strong></td><td>One row: not shipped; do not invent commands</td></tr><tr><td><strong>TRAE Editor for Unity</strong></td><td><a href="https://docs.trae.cn/ide_trae-editor-for-unity-tutorial.md" target="_blank" rel="noreferrer">CN tutorial</a></td><td>One row: Unity plugin</td></tr><tr><td><strong>China site TraeCode / TraeWork</strong></td><td><a href="https://www.trae.cn/" target="_blank" rel="noreferrer">www.trae.cn</a> · Quickstart links <a href="https://www.trae.com.cn" target="_blank" rel="noreferrer">www.trae.com.cn</a> · <a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">docs.trae.cn</a></td><td><a href="./trae.html#1-pick-a-surface-china-vs-international">Tutorial · pick a surface</a></td></tr><tr><td><strong>Volcengine TRAE</strong></td><td><a href="https://www.volcengine.com/product/trae" target="_blank" rel="noreferrer">volcengine.com/product/trae</a></td><td>One row: CN cloud catalog slot</td></tr><tr><td><strong>Doubao</strong></td><td>Issue #79</td><td>One row → forthcoming <a href="/products/doubao/">Doubao family</a></td></tr><tr><td><strong>Coze</strong></td><td>Issue #81</td><td>One row → forthcoming <a href="/products/coze/">Coze family</a></td></tr><tr><td><strong>Ark (Volcengine)</strong></td><td>Issue #82</td><td>One row → <a href="/products/volcengine-ark/">Volcengine Ark</a></td></tr></tbody></table><p>Sources: <a href="https://www.trae.ai/" target="_blank" rel="noreferrer">www.trae.ai</a>, <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai header</a>, <a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">Enterprise</a>, <a href="https://www.trae.cn/" target="_blank" rel="noreferrer">www.trae.cn</a>, <a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer">docs.trae.cn/llms.txt</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TRAE (brand)</span></span>
<span class="line"><span>├── TraeCode — desktop AI coding IDE (this directory)</span></span>
<span class="line"><span>│   ├── IDE mode (editor / terminal / debug / extensions / Git)</span></span>
<span class="line"><span>│   ├── SOLO mode (AI-led: plan → generate → test → preview)</span></span>
<span class="line"><span>│   ├── CUE / Agent / Skills / Rules / MCP</span></span>
<span class="line"><span>│   ├── TraeCode Plugin (VS Code / JetBrains; map row)</span></span>
<span class="line"><span>│   └── TraeCode CLI (official coming soon)</span></span>
<span class="line"><span>├── TraeWork — standalone office workspace (Web / Desktop / Mobile)</span></span>
<span class="line"><span>│   └── Work / Code (marketing page also lists Design)</span></span>
<span class="line"><span>├── TRAE Enterprise — teams</span></span>
<span class="line"><span>└── Same vendor, not this directory</span></span>
<span class="line"><span>    ├── Doubao #79</span></span>
<span class="line"><span>    ├── Coze #81</span></span>
<span class="line"><span>    └── Ark #82</span></span></code></pre></div><p><strong>Names that collide:</strong></p><ul><li><strong>TraeCode ≠ TraeWork.</strong> Coding IDE vs office workspace. Official: <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">TraeWork builds upon TraeCode&#39;s SOLO mode</a>.</li><li><strong>SOLO mode inside TraeCode ≠ TraeWork.</strong> SOLO is the top-left mode switch. TraeWork is a separate client (Web / Desktop / Mobile).</li><li><strong>Legacy names TRAE IDE / TRAE SOLO standalone</strong> folded into TraeCode / TraeWork. Do not install a third product.</li><li><strong>CUE ≠ Cursor.</strong> CUE is TraeCode completion / multi-line edit / next-edit prediction.</li><li><strong>TraeCode Plugin ≠ the in-IDE extension marketplace.</strong> Plugin embeds Trae into VS Code / JetBrains.</li><li><strong><code>trae.ai</code> ≠ <code>trae.cn</code> / <code>trae.com.cn</code>.</strong> The international header has a China-site link. Login, quota, and device limits are separate.</li></ul><h3 id="quick-decision-which-surface" tabindex="-1">Quick decision: which surface? <a class="header-anchor" href="#quick-decision-which-surface" aria-label="Permalink to &quot;Quick decision: which surface?&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What do I want to do?</span></span>
<span class="line"><span>├── Write / edit / debug / complete in a local repo</span></span>
<span class="line"><span>│   └── → TraeCode</span></span>
<span class="line"><span>│       ├── Fine-grained control? → IDE mode</span></span>
<span class="line"><span>│       ├── Natural language through to preview? → SOLO mode</span></span>
<span class="line"><span>│       └── Stay in VS Code / JetBrains? → TraeCode Plugin (map row)</span></span>
<span class="line"><span>├── Slides / docs / data / dispatch tasks across devices</span></span>
<span class="line"><span>│   └── → TraeWork (not this directory)</span></span>
<span class="line"><span>├── Team procurement, repo-index limits, SOC 2</span></span>
<span class="line"><span>│   └── → TRAE Enterprise</span></span>
<span class="line"><span>├── General chat assistant</span></span>
<span class="line"><span>│   └── → Doubao (#79)</span></span>
<span class="line"><span>├── Bots / workflows</span></span>
<span class="line"><span>│   └── → Coze (#81)</span></span>
<span class="line"><span>└── Metered model API in my own service</span></span>
<span class="line"><span>    └── → Ark (#82)</span></span></code></pre></div><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Read</th><th>Goal</th></tr></thead><tbody><tr><td>1. Pick a surface</td><td><a href="./trae.html#1-pick-a-surface-china-vs-international">Tutorial · China vs international</a></td><td>Do not mix installers or accounts</td></tr><tr><td>2. Install and open a project</td><td><a href="./trae.html">Tutorial</a></td><td>Official download, then a local folder or clone</td></tr><tr><td>3. Split the two modes</td><td><a href="./trae.html#5-switch-ide-mode-and-solo-mode">Tutorial · IDE / SOLO</a></td><td>Top-left switch; SOLO is not TraeWork</td></tr><tr><td>4. Look up facts</td><td><a href="./trae-cheatsheet.html">Cheatsheet</a></td><td>OS, device limit, official URLs</td></tr></tbody></table><h2 id="feature-lookup" tabindex="-1">Feature lookup <a class="header-anchor" href="#feature-lookup" aria-label="Permalink to &quot;Feature lookup&quot;">​</a></h2><p>Only capabilities the official docs already state.</p><table tabindex="0"><thead><tr><th>Capability</th><th>One line</th><th>Official page</th></tr></thead><tbody><tr><td>IDE mode</td><td>Editor, terminal, debug, extensions, source control</td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a></td></tr><tr><td>SOLO mode</td><td>AI-led: requirements → generate → test → preview; top-left switch</td><td><a href="https://docs.trae.ai/ide/solo-mode" target="_blank" rel="noreferrer">SOLO mode overview</a></td></tr><tr><td>Open a project</td><td>Local folder / clone from GitHub / clone from URL</td><td><a href="https://docs.trae.ai/ide/set-up-trae" target="_blank" rel="noreferrer">Quickstart</a></td></tr><tr><td>CUE</td><td>Completion, chained completion, multi-line edits, next-edit prediction; smart import/rename for Py / TS / Go</td><td><a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">What is TraeCode?</a></td></tr><tr><td>Agents</td><td>Natural-language tasks, repo search, tools; custom agents + MCP</td><td>Same</td></tr><tr><td>Context</td><td>Files, folders, snippets, terminal, repos, doc sets, web pages</td><td>Same</td></tr><tr><td>Privacy mode</td><td>Chats / snippets / outputs not used for analysis, optimization, or training; codebase stays local</td><td>Same</td></tr><tr><td>Sandbox</td><td>Agent commands in a restricted environment</td><td>Same</td></tr><tr><td>Remote</td><td>Remote SSH, WSL</td><td>Same</td></tr><tr><td>Device limit</td><td>International <strong>3</strong>; China <strong>10</strong>. TraeWork Web does not count</td><td><a href="https://docs.trae.ai/ide/device-limit" target="_blank" rel="noreferrer">intl</a> · <a href="https://docs.trae.cn/ide_device-limit.md" target="_blank" rel="noreferrer">CN</a></td></tr></tbody></table><h2 id="plans-official-pages-only" tabindex="-1">Plans (official pages only) <a class="header-anchor" href="#plans-official-pages-only" aria-label="Permalink to &quot;Plans (official pages only)&quot;">​</a></h2><ul><li>Current international tiers: <a href="https://www.trae.ai/pricing" target="_blank" rel="noreferrer">www.trae.ai/pricing</a> — <strong>Lite / Pro / Pro+ / Ultra</strong>. That page says Pro is <strong>Free for 7 days. Then $10/month.</strong> AI requests are billed as tokens converted to Dollar Usage against a monthly balance. Full monthly prices for Lite / Pro+ / Ultra stay on that page.</li><li>Docs also keep <a href="https://docs.trae.ai/ide/billing" target="_blank" rel="noreferrer">(Legacy) Plans &amp; billing</a>. Do not treat the old Free/Pro request table as current.</li><li>China-site credits: follow <a href="https://docs.trae.cn/llms.txt" target="_blank" rel="noreferrer">docs.trae.cn</a>. This site does not invent CN prices.</li><li>Enterprise: pricing page says Contact us via BytePlus; product page <a href="https://www.trae.ai/enterprise" target="_blank" rel="noreferrer">Enterprise</a>.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li>Open the <a href="./trae.html">TraeCode tutorial</a>. Pick China or international, then install from the official download page.</li><li>OS, device limits, and URLs: <a href="./trae-cheatsheet.html">cheatsheet</a>.</li><li>Official deep-dive: <a href="https://docs.trae.ai/ide/what-is-trae" target="_blank" rel="noreferrer">docs.trae.ai</a> or <a href="https://docs.trae.cn/ide_what-is-trae-code" target="_blank" rel="noreferrer">docs.trae.cn</a>.</li></ol>`,22)])])}const w=t(s,[["render",o]]);export{m as __pageData,w as default};
